  ui_story_30780601_95_dialog_content = "<color=#e8d9bb>No calor do sol da tarde, uma soneca curta pode facilmente se estender por horas...</color>",
  ui_story_30780601_96_dialog_content = "Zzzz... Zzzz... Hum?",
  ui_story_30780601_97_dialog_content = "(Oh não, eu adormeci! Por quanto tempo eu estive fora?)",
  ui_story_30780601_98_dialog_content = "(Isso é ruim, eu deveria estar contando mais sobre esses livros para Robyn! Espero que ela não esteja muito...)",
  ui_story_30780601_99_dialog_content = "Zzzz... Zzzz...",
  ui_story_30780601_100_dialog_content = "Ah... Ela também está dormindo?",
  ui_story_30780601_101_dialog_content = "O sol está um pouco brilhante demais agora. Eu deveria fechar as cortinas para Robyn.",
  ui_story_30780601_102_dialog_content = "Mas... Estou preocupado que eu possa acordá-la.",
  ui_story_30780601_103_dialog_content = "Eu teria que passar por cima dela e esticar o braço por cima da mesa dela para fechá-las.",
  ui_story_30780601_104_dialog_content = "Não será fácil, mas eu tenho que tentar!",
  ui_story_30780601_105_dialog_content = "Zzzz... Hum?",
  ui_story_30780601_106_dialog_content = "Ah, desculpe... Eu te acordei?",
  ui_story_30780601_107_dialog_content = "Hmm... Não... Na verdade não...",
  ui_story_30780601_108_dialog_content = "Eu... acordei por conta própria.",
  ui_story_30780601_109_dialog_content = "Foi um sonho tão bom... Eu continuava me dizendo que não podia ficar dormindo para sempre...",
  ui_story_30780601_110_dialog_content = "Sério? Sobre o que era, Robyn?",
  ui_story_30780601_111_dialog_content = "Sonhei com o céu e o mar, com montanhas e florestas... e nós. Sonhei que estávamos voando por tudo isso.",
  ui_story_30780601_112_dialog_content = "\"Nós\"?",
  ui_story_30780601_113_dialog_content = "Isso mesmo, PlayerName, você e eu...",
  ui_story_30780601_114_dialog_content = "Estávamos flutuando na brisa como penas... e à deriva nas ondas do oceano...",
  ui_story_30780601_115_dialog_content = "Ouvindo as cigarras na floresta... e correndo por um lago de lotus após a chuva...",
  ui_story_30780601_116_dialog_content = "Isso parece um sonho maravilhoso...",
  ui_story_30780601_117_dialog_content = "Tenho quase certeza de que tinha algo a ver com o livro que eu estava lendo...",
  ui_story_30780601_118_dialog_content = "Há algo verdadeiramente mágico sobre prosa e poesia narrativa...",
  ui_story_30780601_119_dialog_content = "Havia até alguns poemas de Longzhou... Embora eu não pudesse entender completamente o seu significado, entendi o suficiente para sentir a sua arte.",
  ui_story_30780601_120_dialog_content = "Você quer ler alguns deles comigo, PlayerName?",
  ui_story_30780601_121_dialog_content = "Uh... Claro, mas não sou exatamente um especialista no assunto... Minhas interpretações também podem não ser muito precisas.",
  ui_story_30780601_122_dialog_content = "Se isso não for um problema para você, então eu adoraria ler alguns poemas com você.",
  ui_story_30780601_123_dialog_content = "De jeito nenhum... Aqui, vou compartilhar meu assento com você.",
  ui_story_30780601_124_dialog_content = "Está bem, mas tem certeza disso? Vamos ficar sentados muito perto um do outro...",
  ui_story_30780601_125_dialog_content = "Vou ficar bem. Está tão quente...",
  ui_story_30780601_126_dialog_content = "Quente? Sim, o sol está bem quente hoje...",
  ui_story_30780601_127_dialog_content = "Hehe, com certeza é...",
  ui_story_30780601_128_dialog_content = "Aqui... Este é o verso que eu estava lendo antes de adormecer...",
  ui_story_30780601_129_dialog_content = "Vamos ver aqui...",
  ui_story_30780601_130_dialog_content = "\"Os ventos do sul conhecem meu coração e sopram meus sonhos para o oeste.\"",
  ui_story_30780601_131_dialog_content = "Então... O que isso significa?",
  ui_story_30780601_132_dialog_content = "Se eu tivesse que adivinhar... O autor quer visitar um lugar distante em seus sonhos e compartilhar seus sentimentos com alguém lá... Talvez sua cidade natal?",
  ui_story_30780601_133_dialog_content = "A cidade natal deles... Minha cidade natal...",
  ui_story_30780601_134_dialog_content = "Hã? O que é, Robyn?",
  ui_story_30780601_135_dialog_content = "Não é nada... Então, você sonhou com alguma coisa, PlayerName?",
  ui_story_30780601_136_dialog_content = "Bem... Eu acordei tão de repente que realmente não consigo me lembrar de nada.",
  ui_story_30780601_137_dialog_content = "Mas, logo antes de adormecer, vi você lendo silenciosamente à luz do sol. Foi uma visão tão calma e tranquila.",
  ui_story_30780601_138_dialog_content = "Tenho quase certeza de que você passou essa sensação de paz para mim, é por isso que dormi tão bem agora!",
  ui_story_30780601_139_dialog_content = "Entendo...",
  ui_story_30780601_140_dialog_content = "Além de Dayna, nunca me senti tão relaxado perto de outra pessoa...",
  ui_story_30780601_141_dialog_content = "É só que... Eu ainda não expliquei nenhum desses livros para você. Desculpe!",
  ui_story_30780601_142_dialog_content = "Não seja. Quando você está aqui comigo, sinto que posso me concentrar ainda melhor na minha leitura.",
  ui_story_30780601_143_dialog_content = "Na verdade... Há outro tipo de livro que eu quero ler com você, PlayerName...",
  ui_story_30780601_144_dialog_content = "A poesia é boa e tudo mais, mas tende a deixar as pessoas sonolentas... Os livros que estou pensando são para realmente prender a atenção do leitor, quase como mágica.",
  ui_story_30780601_145_dialog_content = "Ah? Então, que tipo de livros são eles?",
  ui_story_30780601_146_dialog_content = "São essas histórias realmente aceleradas, do tipo com heróis insanamente poderosos que defendem a justiça e lutam contra o mal.",
  ui_story_30780601_147_dialog_content = "Ouço os comerciantes de Umbraton falando sobre eles de vez em quando...",
  ui_story_30780601_148_dialog_content = "Aposto que é fácil se envolver com livros assim, não acha?",
  ui_story_30780601_149_dialog_content = "Acho que tudo depende da qualidade da história.",
  ui_story_30780601_150_dialog_content = "Isso... não deve ser um problema.",
  ui_story_30780601_151_dialog_content = "Há uma certa história ganhando popularidade em Umbraton nos dias de hoje... É sobre um lendário espadachim. Eu adoraria conseguir uma cópia...",
  ui_story_30780601_152_dialog_content = "Não consigo me lembrar do nome, mas você pode dizer que vem direto de Longzhou... Você sabe de qual história estou falando, PlayerName?",
  ui_story_30780601_153_dialog_content = "Um espadachim lendário... Espere, eu sei de quem você está falando! Você está com sorte também, porque eu conheço isso como a palma da minha mão!",
  ui_story_30780601_154_dialog_content = "Vou te contar a história inteira agora mesmo, então fique confortável!"
}
